/**
 * Length specifications for the three reply variations.
 *
 * Each variation is generated by a SEPARATE LLM call with the same context
 * but a different length instruction — this keeps the three drafts
 * independent (the model isn't tempted to make them all converge to one
 * length) and lets us parallelise the calls in the future.
 */

export type LengthKey = 'short' | 'medium' | 'detailed'

export interface LengthSpec {
  length: LengthKey
  /** [min, max] sentence count — used for short & medium. */
  sentences: [number, number]
  /** [min, max] paragraph count — used primarily for detailed. */
  paragraphs: [number, number]
  /** Human label shown in the UI card header. */
  label: string
  /** Instruction string injected into the user prompt. */
  instruction: string
}

/**
 * Returns the canonical three length specs.
 *
 * - short   : 1–3 sentences, single paragraph  (a quick acknowledgement)
 * - medium  : 4–7 sentences, 1–2 paragraphs      (the "default" reply)
 * - detailed: 2–3 paragraphs                    (thorough, multi-point reply)
 */
export function getLengthSpecs(): LengthSpec[] {
  return [
    {
      length: 'short',
      sentences: [1, 3],
      paragraphs: [1, 1],
      label: 'Short',
      instruction:
        'Write a very short reply: 1 to 3 sentences in a single paragraph. Acknowledge the email and respond directly. Do not add filler.',
    },
    {
      length: 'medium',
      sentences: [4, 7],
      paragraphs: [1, 2],
      label: 'Medium',
      instruction:
        'Write a medium-length reply: 4 to 7 sentences across 1 to 2 paragraphs. Address each point the sender raised.',
    },
    {
      length: 'detailed',
      sentences: [6, 12],
      paragraphs: [2, 3],
      label: 'Detailed',
      instruction:
        'Write a detailed reply: 2 to 3 paragraphs. Thoroughly cover every point, add context where useful, and propose clear next steps.',
    },
  ]
}

/** Look up a single length spec by key. Throws for unknown keys. */
export function getLengthSpec(key: LengthKey): LengthSpec {
  const spec = getLengthSpecs().find((s) => s.length === key)
  if (!spec) throw new Error(`Unknown length key: ${key}`)
  return spec
}
